CREATE TABLE permission_definitions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), permission_key TEXT UNIQUE NOT NULL, object_key TEXT NOT NULL, action TEXT NOT NULL, description TEXT NOT NULL, risk_level TEXT NOT NULL, status TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE role_definitions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id), role_key TEXT NOT NULL, name TEXT NOT NULL, description TEXT NOT NULL, role_type TEXT NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(workspace_id,role_key,version));
CREATE TABLE permission_grants (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id), user_id UUID NOT NULL REFERENCES user_identities(id), permission_key TEXT NOT NULL REFERENCES permission_definitions(permission_key), effect TEXT NOT NULL CHECK(effect IN ('ALLOW','DENY','CONDITIONAL')), scope_type TEXT NOT NULL, scope_id UUID, source_type TEXT NOT NULL, source_id UUID NOT NULL, effective_from TIMESTAMPTZ NOT NULL, effective_to TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX permission_grants_effective_idx ON permission_grants(workspace_id,user_id,permission_key,effect);
CREATE TABLE field_permissions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id), principal_type TEXT NOT NULL, principal_id UUID NOT NULL, object_key TEXT NOT NULL, field_key TEXT NOT NULL, can_view BOOLEAN NOT NULL DEFAULT false, can_export BOOLEAN NOT NULL DEFAULT false, masking_mode TEXT NOT NULL DEFAULT 'FULL', priority INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE delegations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id), delegator_user_id UUID NOT NULL, delegate_user_id UUID NOT NULL, delegated_permissions JSONB NOT NULL, scope_type TEXT NOT NULL, scope_id UUID, authority_limit_minor BIGINT, currency TEXT, reason TEXT NOT NULL, status TEXT NOT NULL, effective_from TIMESTAMPTZ NOT NULL, effective_to TIMESTAMPTZ NOT NULL, approved_by UUID, revoked_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), version INTEGER NOT NULL DEFAULT 1, CHECK(authority_limit_minor IS NULL OR authority_limit_minor >= 0));
CREATE TABLE authority_rules (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id), transaction_type TEXT NOT NULL, required_permission TEXT NOT NULL, maximum_value_minor BIGINT, currency TEXT, required_approval_count INTEGER NOT NULL DEFAULT 1, independence_required BOOLEAN NOT NULL DEFAULT false, status TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE segregation_rules (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id), rule_key TEXT NOT NULL, first_permission TEXT NOT NULL, conflicting_permission TEXT NOT NULL, severity TEXT NOT NULL, enforcement_mode TEXT NOT NULL, status TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), version INTEGER NOT NULL DEFAULT 1, UNIQUE(workspace_id,rule_key));
